import re
import datetime

def standardize_date_time(value):
    # Remove any non-alphanumeric characters except for colons and spaces
    value = re.sub(r'[^a-zA-Z0-9 :]+', '', value)

    # Split the string into date, time, and AM/PM or Z
    parts = value.split()

    # If there are less than 3 parts, assume it's in a 24-hour format
    if len(parts) < 3:
        date_part, time_part = parts[0], parts[1]
    else:
        date_part, time_part, am_pm_or_z = parts
        # If AM/PM is provided, convert to 24-hour format
        if am_pm_or_z.lower() in ['am', 'pm']:
            hour = int(time_part.split(':')[0])
            if time_part.split(':')[1].endswith(' pm') and hour != 12:
                hour += 12
            elif time_part.split(':')[1].endswith(' am'):
                hour -= 12
        else:
            # Assume it's in a 24-hour format if Z is provided
            pass

    # Convert the date part to datetime object
    try:
        date = datetime.datetime.strptime(date_part, '%Y-%m-%d')
    except ValueError:
        # If it's not in YYYY-MM-DD format, assume it's MM/DD/YYYY or DD.MM.YYYY
        if '/' in date_part:
            date = datetime.datetime.strptime(date_part, '%m/%d/%Y')
        elif '.' in date_part:
            date = datetime.datetime.strptime(date_part, '%d.%m.%Y')
        else:
            raise ValueError("Unable to parse the date part.")

    # Convert the time part to datetime object
    try:
        time = datetime.time.strptime(time_part, '%H:%M:%S')
    except ValueError:
        raise ValueError("Unable to parse the time part.")

    # Combine date and time objects to get a single datetime object
    result = datetime.datetime.combine(date, time)

    return result.strftime('%Y-%m-%d %H:%M:%S')

# Apply the function to each row in the act_dep_time column
data['act_dep_time'] = data['act_dep_time'].apply(standardize_date_time)
